import React from 'react';
import './css/EmailDetail.css';
import {Email} from './EmailList';

interface EmailDetailProps {
    email:Email | null;
}

export const EmailDetail: React.FC<EmailDetailProps> = ({ email }) => {
    const formartDate =(datestring  : string) : string => {
        const option:Intl.DateTimeFormatOptions = {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
        };
        return new Date(datestring).toLocaleDateString(undefined, option);
    };
    
    if (!email){
        return (
            <div className="email-detail__placeholder">
                <i className= "fas fa-envelope-text email-detail__icon"></i>
                <p className="email-detail__message">select an email to read</p>
            </div>
        );
    }

    return (
        <div className="email-detail">
            <div className ="email-detail__header">
                <img src ={email.avatarUrl} alt= {'Avatar of ${email.sender}'} className="email-detail__avatar" />
                <div className ="email-detail__info">
                <h2 className ="email-detail__subject">{email.subject}</h2>
                </div>
            </div>
        </div>
    );
};
